# Villa 2: arched window / door families, generated by editing the project's own generic families.
# For every spec the family M_Fixed (windows) or M_Single-Flush (doors) is opened with EditFamily, its geometry is replaced
# by: a void extrusion with the arch profile (cuts the wall), a frame ring and a glass pane (or door leaves), and the result
# is loaded back into the project under the spec's name. No template files are needed.
# DATA = dict(specs=[{name, kind: 'window'|'door', w, h, shape: rect|round|segmental|horseshoe, rise, frame, inset, leaves}])  metres.
import math
import System

def arch_loops(w, h, shape, rise=0.0, d=0.0, off=0.0):
    """Closed loop in (x, z) metres: bottom centre at z=0. Returns list of ('L', p, q) / ('A', p, mid, q) segments."""
    hw = w / 2.0 - off
    top = h - off
    segs = []
    z0 = off
    if shape == "rect":
        pts = [(-hw, z0), (hw, z0), (hw, top), (-hw, top)]
        for i in range(4): segs.append(("L", pts[i], pts[(i + 1) % 4]))
        return segs
    if shape == "segmental":
        spring = top - rise
        mid = (0.0, top)
        segs += [("L", (-hw, z0), (hw, z0)), ("L", (hw, z0), (hw, spring)), ("A", (hw, spring), mid, (-hw, spring)), ("L", (-hw, spring), (-hw, z0))]
        return segs
    if shape == "round":
        spring = top - hw
        segs += [("L", (-hw, z0), (hw, z0)), ("L", (hw, z0), (hw, spring)), ("A", (hw, spring), (0.0, spring + hw), (-hw, spring)), ("L", (-hw, spring), (-hw, z0))]
        return segs
    if shape == "horseshoe":
        rho = math.sqrt(hw * hw + d * d)
        spring = top - (d + rho)
        # the arc is more than a half circle: three points on it are the two spring points and the apex
        segs += [("L", (-hw, z0), (hw, z0)), ("L", (hw, z0), (hw, spring)), ("A", (hw, spring), (0.0, top), (-hw, spring)), ("L", (-hw, spring), (-hw, z0))]
        return segs
    raise Exception("unknown shape " + shape)

def to_curveloop(segs, y):
    cl = CurveLoop()
    for s in segs:
        if s[0] == "L":
            a, b = s[1], s[2]
            cl.Append(Line.CreateBound(XYZ(a[0] / FT, y / FT, a[1] / FT), XYZ(b[0] / FT, y / FT, b[1] / FT)))
        else:
            a, m, b = s[1], s[2], s[3]
            cl.Append(Arc.Create(XYZ(a[0] / FT, y / FT, a[1] / FT), XYZ(b[0] / FT, y / FT, b[1] / FT), XYZ(m[0] / FT, y / FT, m[1] / FT)))
    return cl

def build_family(fd, spec):
    """Replace the geometry inside the opened family document fd."""
    # remove old solids / voids / openings
    kill = []
    for e in FilteredElementCollector(fd).WhereElementIsNotElementType():
        if isinstance(e, GenericForm) or (e.Category is not None and e.Category.Name == "Opening cut"):
            kill.append(e.Id)
    for i in kill:
        try: fd.Delete(i)
        except: pass
    fd.Regenerate()
    # work plane: the wall centre plane (Center (Front/Back)) is the XZ plane at y = 0
    plane = Plane.CreateByNormalAndOrigin(XYZ.BasisY, XYZ.Zero)
    sp = SketchPlane.Create(fd, plane)
    fm = fd.FamilyManager
    def fam_mat(name, rgb, transp=0):
        for m in FilteredElementCollector(fd).OfClass(Material):
            if m.Name == name: return m.Id
        mid = Material.Create(fd, name); m = fd.GetElement(mid); m.Color = Color(*rgb)
        if transp: m.Transparency = transp
        return mid
    M_GLASS = fam_mat("AMB2_Glass", (190, 215, 225), 60); M_FRAME = fam_mat("AMB2_Frame", (70, 58, 50)); M_LEAF = fam_mat("AMB2_Timber", (110, 72, 44))
    cat = fd.OwnerFamily.FamilyCategory
    def subcat(name):
        try: return cat.SubCategories.get_Item(name)
        except: return None
    def style(ex, mat, sub):
        try: ex.get_Parameter(BuiltInParameter.MATERIAL_ID_PARAM).Set(mat)
        except Exception as e: pass
        sc = subcat(sub)
        if sc is not None:
            try: ex.Subcategory = sc
            except Exception as e: pass
    w, h, shape = spec["w"], spec["h"], spec["shape"]
    # The family's own Width/Height must equal the geometry (project-side edits would otherwise rescale it), and a window's
    # geometry has to start at the family's sill reference plane, because the instance is placed with origin = sill - default sill.
    zoff = 0.0
    try:
        pw, ph = fm.get_Parameter("Width"), fm.get_Parameter("Height")
        if pw is not None: fm.Set(pw, w / FT)
        if ph is not None: fm.Set(ph, h / FT)
        fd.Regenerate()
        if spec["kind"] == "window":
            ps = fm.get_Parameter("Default Sill Height")
            zoff = fm.CurrentType.AsDouble(ps) * FT if ps is not None else 0.0
    except Exception as e:
        zoff = 0.915 if spec["kind"] == "window" else 0.0
    # keep one type only, named like the family
    try:
        cur = fm.CurrentType
        for tt in list(fm.Types):
            if tt.Name != cur.Name:
                fm.CurrentType = tt; fm.DeleteCurrentType()
        fm.CurrentType = cur if cur is not None else fm.Types.get_Item(0)
        fm.RenameCurrentType(spec["name"])
    except Exception as e:
        pass
    rise = spec.get("rise", 0.0); d = spec.get("d", 0.12 * w)
    depth = spec.get("depth", 0.30)                       # wall thickness cut by the void
    def extrude(loops, y0, y1, solid, subcat=None):
        arr = CurveArrArray()
        for cl in loops:
            ca = CurveArray()
            for c in cl: ca.Append(c)
            arr.Append(ca)
        ex = fd.FamilyCreate.NewExtrusion(solid, arr, sp, (y1 - y0) / FT)
        ex.StartOffset = y0 / FT; ex.EndOffset = y1 / FT
        return ex
    def segs_to_curves(segs):
        out = []
        for s in segs:
            if s[0] == "L":
                a, b = s[1], s[2]; out.append(Line.CreateBound(XYZ(a[0] / FT, 0, (a[1] + zoff) / FT), XYZ(b[0] / FT, 0, (b[1] + zoff) / FT)))
            else:
                a, m, b = s[1], s[2], s[3]; out.append(Arc.Create(XYZ(a[0] / FT, 0, (a[1] + zoff) / FT), XYZ(b[0] / FT, 0, (b[1] + zoff) / FT), XYZ(m[0] / FT, 0, (m[1] + zoff) / FT)))
        return out
    outer = arch_loops(w, h, shape, rise, d, 0.0)
    # void that cuts the wall
    f = spec.get("frame", 0.06)
    inner = arch_loops(w, h, shape, rise, d, f)
    inset = spec.get("inset", 0.04)
    # frame ring = outer loop + inner loop (a hole)
    style(extrude([segs_to_curves(outer), segs_to_curves(inner)], -0.07 + inset, 0.07 + inset, True), M_FRAME, "Frame/Mullion")
    if spec["kind"] == "window":
        style(extrude([segs_to_curves(inner)], -0.01 + inset, 0.01 + inset, True), M_GLASS, "Glass")
    else:
        # door: two timber leaves up to the leaf height, glazed fanlight above (if the opening is taller than the leaves)
        lh = min(spec.get("leaf_h", h), h - f)
        leaves = [(-w / 2 + f, -0.01, 0.0, -0.0), (0.01, w / 2 - f, 0.0, 0.0)]
        for (x0, x1, _a, _b) in leaves:
            ring = [("L", (x0, f), (x1, f)), ("L", (x1, f), (x1, lh)), ("L", (x1, lh), (x0, lh)), ("L", (x0, lh), (x0, f))]
            style(extrude([segs_to_curves(ring)], -0.02 + inset, 0.02 + inset, True), M_LEAF, "Panel")
        if h - f > lh + 0.05:
            # fanlight: the arch profile above the leaf line
            top = arch_loops(w, h, shape, rise, d, f)
            fan = [s for s in top]
            # clip: rebuild as polygon-with-arch above lh by intersecting with a box is not available in the API, so use the full inner profile as glass behind the leaves
            style(extrude([segs_to_curves(inner)], -0.012 + inset, 0.012 + inset, True), M_GLASS, "Glass")

def make_family(spec):
    base = "M_Fixed" if spec["kind"] == "window" else "M_Single-Flush"
    fam = [f for f in FilteredElementCollector(doc).OfClass(Family) if f.Name == base][0]
    fd = doc.EditFamily(fam)
    try:
        t = Transaction(fd, "AMB2: arch family " + spec["name"]); t.Start()
        try:
            build_family(fd, spec)
            t.Commit()
        except Exception as e:
            t.RollBack(); raise
        class Opt(IFamilyLoadOptions):
            def OnFamilyFound(self, inUse, overwrite): return True
            def OnSharedFamilyFound(self, shared, inUse, source, overwrite): return True
        so = SaveAsOptions(); so.OverwriteExistingFile = True
        fd.SaveAs(System.IO.Path.Combine(System.IO.Path.GetTempPath(), spec["name"] + ".rfa"), so)
        fam2 = fd.LoadFamily(doc, Opt())
        return fam2
    finally:
        fd.Close(False)


def make_void_family(spec):
    """A Generic Model family that contains only a void extrusion with the arch profile. A project instance of it cuts any wall
    via InstanceVoidCutUtils.AddInstanceVoidCut. (A family Opening / void form inside a door or window family did NOT cut the
    host for arch profiles - measured with rays.) The profile runs from z=0 (sill) to z=h; depth is along the family Y axis."""
    base = [f for f in FilteredElementCollector(doc).OfClass(Family) if f.Name == "Pole"][0]
    fd = doc.EditFamily(base)
    try:
        t = Transaction(fd, "AMB2: void family " + spec["name"]); t.Start()
        try:
            for e in list(FilteredElementCollector(fd).OfClass(GenericForm)) + list(FilteredElementCollector(fd).OfClass(FamilyInstance)):
                try: fd.Delete(e.Id)
                except: pass
            fd.Regenerate()
            sp = SketchPlane.Create(fd, Plane.CreateByNormalAndOrigin(XYZ.BasisY, XYZ.Zero))
            segs = arch_loops(spec["w"], spec["h"], spec["shape"], spec.get("rise", 0.0), spec.get("d", 0.0), 0.0)
            ca = CurveArray()
            for s in segs:
                if s[0] == "L": ca.Append(Line.CreateBound(XYZ(s[1][0] / FT, 0, s[1][1] / FT), XYZ(s[2][0] / FT, 0, s[2][1] / FT)))
                else: ca.Append(Arc.Create(XYZ(s[1][0] / FT, 0, s[1][1] / FT), XYZ(s[3][0] / FT, 0, s[3][1] / FT), XYZ(s[2][0] / FT, 0, s[2][1] / FT)))
            arr = CurveArrArray(); arr.Append(ca)
            depth = spec.get("depth", 0.7)
            ex = fd.FamilyCreate.NewExtrusion(False, arr, sp, depth / FT)
            ex.StartOffset = -depth / 2.0 / FT; ex.EndOffset = depth / 2.0 / FT
            t.Commit()
        except Exception as e:
            t.RollBack(); raise
        class Opt(IFamilyLoadOptions):
            def OnFamilyFound(self, inUse, overwrite): return True
            def OnSharedFamilyFound(self, shared, inUse, source, overwrite): return True
        so = SaveAsOptions(); so.OverwriteExistingFile = True
        fd.SaveAs(System.IO.Path.Combine(System.IO.Path.GetTempPath(), spec["name"] + ".rfa"), so)
        return fd.LoadFamily(doc, Opt())
    finally:
        fd.Close(False)
